import React, { useEffect, useState } from 'react';
import API from '../api';
import { useNavigate, Link } from 'react-router-dom';
import { addToCart } from '../cart';
import { isAdmin } from '../auth';

function Products() {
  const [products, setProducts] = useState([]);
  const [filtered, setFiltered] = useState([]);
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState('default');
  const [category, setCategory] = useState('all');
  const [categories, setCategories] = useState([]);
  const [error, setError] = useState('');
  const [added, setAdded] = useState({});
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const navigate = useNavigate();
  const token = localStorage.getItem('token');

  useEffect(() => { fetchProducts(); }, []);
  useEffect(() => { applyFilters(); }, [search, sortBy, category, products]);

  const fetchProducts = async () => {
    try {
      const res = await API.get('/products/');
      setProducts(res.data);
      setFiltered(res.data);
      const cats = [...new Set(res.data.map(p => p.category).filter(Boolean))];
      setCategories(cats);
    } catch (err) {
      setError('Failed to load products');
    }
  };

  const applyFilters = () => {
    let result = [...products];
    if (category !== 'all') result = result.filter(p => p.category === category);
    if (search) result = result.filter(p =>
      p.name.toLowerCase().includes(search.toLowerCase()) ||
      p.description.toLowerCase().includes(search.toLowerCase())
    );
    if (sortBy === 'low') result.sort((a, b) => a.price - b.price);
    else if (sortBy === 'high') result.sort((a, b) => b.price - a.price);
    else if (sortBy === 'name') result.sort((a, b) => a.name.localeCompare(b.name));
    setFiltered(result);
  };

  const handleAddToCart = (product) => {
    addToCart(product);
    setAdded(prev => ({ ...prev, [product.id]: true }));
    setTimeout(() => setAdded(prev => ({ ...prev, [product.id]: false })), 1500);
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  const activeFiltersCount = (category !== 'all' ? 1 : 0) + (sortBy !== 'default' ? 1 : 0);

  return (
    <div style={styles.container}>
      {/* Navbar */}
      <div style={styles.navbar}>
        <h2 style={styles.logo}>🛒 Ecommerce</h2>
        <div style={styles.navLinks}>
          {isAdmin() && <Link to="/admin/products" style={styles.adminLink}>⚙️ Admin Panel</Link>}
          <Link to="/cart" style={styles.navLink}>🛒 Cart</Link>
          {token ? (
            <>
              <Link to="/orders" style={styles.navLink}>My Orders</Link>
              <button onClick={handleLogout} style={styles.logoutBtn}>Logout</button>
            </>
          ) : (
            <Link to="/login" style={styles.navLink}>Login</Link>
          )}
        </div>
      </div>

      {/* Hero Search Bar */}
      <div style={styles.hero}>
        <h3 style={styles.heroTitle}>Find What You Love</h3>
        <div style={styles.heroSearch}>
          <span style={styles.searchIcon}>🔍</span>
          <input
            style={styles.searchInput}
            type="text"
            placeholder="Search products..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          {search && (
            <span style={styles.clearSearch} onClick={() => setSearch('')}>✕</span>
          )}
        </div>
      </div>

      <div style={styles.layout}>
        {/* Sidebar */}
        <div style={{
          ...styles.sidebarWrapper,
          width: sidebarOpen ? '230px' : '0px',
          opacity: sidebarOpen ? 1 : 0,
          transition: 'width 0.35s cubic-bezier(0.4,0,0.2,1), opacity 0.25s ease',
          overflow: 'hidden',
          flexShrink: 0,
        }}>
          <div style={styles.sidebar}>
            <div style={styles.sidebarHeader}>
              <span style={styles.sidebarHeaderText}>🎛️ Filters</span>
              {activeFiltersCount > 0 && (
                <span style={styles.filterBadge}>{activeFiltersCount}</span>
              )}
            </div>

            <div style={styles.filterSection}>
              <p style={styles.filterLabel}>CATEGORIES</p>
              <div
                style={{ ...styles.filterChip, ...(category === 'all' ? styles.filterChipActive : {}) }}
                onClick={() => setCategory('all')}
              >
                All Products
              </div>
              {categories.map(cat => (
                <div
                  key={cat}
                  style={{ ...styles.filterChip, ...(category === cat ? styles.filterChipActive : {}) }}
                  onClick={() => setCategory(cat)}
                >
                  {cat}
                </div>
              ))}
            </div>

            <div style={styles.filterSection}>
              <p style={styles.filterLabel}>SORT BY PRICE</p>
              <div
                style={{ ...styles.filterChip, ...(sortBy === 'low' ? styles.filterChipActive : {}) }}
                onClick={() => setSortBy(sortBy === 'low' ? 'default' : 'low')}
              >
                💰 Low to High
              </div>
              <div
                style={{ ...styles.filterChip, ...(sortBy === 'high' ? styles.filterChipActive : {}) }}
                onClick={() => setSortBy(sortBy === 'high' ? 'default' : 'high')}
              >
                💎 High to Low
              </div>
              <div
                style={{ ...styles.filterChip, ...(sortBy === 'name' ? styles.filterChipActive : {}) }}
                onClick={() => setSortBy(sortBy === 'name' ? 'default' : 'name')}
              >
                🔤 Name A-Z
              </div>
            </div>

            {activeFiltersCount > 0 && (
              <button
                style={styles.resetBtn}
                onClick={() => { setCategory('all'); setSortBy('default'); setSearch(''); }}
              >
                Reset Filters
              </button>
            )}
          </div>
        </div>

        {/* Main */}
        <div style={styles.main}>
          {/* Top bar */}
          <div style={styles.topBar}>
            {/* Filter toggle pill */}
            <button style={styles.filterToggle} onClick={() => setSidebarOpen(!sidebarOpen)}>
              <span>⚡ Filters</span>
              {activeFiltersCount > 0 && (
                <span style={styles.toggleBadge}>{activeFiltersCount}</span>
              )}
              <span style={{ fontSize: '11px', opacity: 0.8 }}>{sidebarOpen ? '◀' : '▶'}</span>
            </button>

            <p style={styles.resultCount}>
              <strong>{filtered.length}</strong> product{filtered.length !== 1 ? 's' : ''}
              {category !== 'all' && <span style={styles.filterTag}>{category} ✕</span>}
            </p>

            <select style={styles.select} value={sortBy} onChange={(e) => setSortBy(e.target.value)}>
              <option value="default">Sort By</option>
              <option value="low">Price: Low to High</option>
              <option value="high">Price: High to Low</option>
              <option value="name">Name: A to Z</option>
            </select>
          </div>

          {error && <p style={styles.error}>{error}</p>}

          {filtered.length === 0 && !error && (
            <div style={styles.noResults}>
              <p style={{ fontSize: '40px' }}>🔍</p>
              <p>No products found.</p>
              <button style={styles.clearBtn} onClick={() => { setSearch(''); setSortBy('default'); setCategory('all'); }}>
                Clear All Filters
              </button>
            </div>
          )}

          <div style={styles.grid}>
            {filtered.map((p) => (
              <div key={p.id} style={styles.card}>
                {p.image_url ? (
                  <img src={p.image_url} alt={p.name} style={styles.productImg} onError={(e) => e.target.style.display = 'none'} />
                ) : (
                  <div style={styles.noImg}>No Image</div>
                )}
                <div style={styles.cardBody}>
                  <div style={styles.cardTop}>
                    {p.category && <span style={styles.categoryBadge}>{p.category}</span>}
                    {p.stock === 0 && <span style={styles.outOfStockBadge}>Out of Stock</span>}
                    {p.stock > 0 && p.stock <= 5 && <span style={styles.lowStockBadge}>Only {p.stock} left!</span>}
                  </div>
                  <h4 style={styles.productName}>{p.name}</h4>
                  <p style={styles.desc}>{p.description}</p>
                  <div style={styles.cardFooter}>
                    <p style={styles.price}>${p.price}</p>
                    <button
                      style={{
                        ...styles.cartBtn,
                        background: added[p.id] ? '#4CAF50' : p.stock === 0 ? '#ccc' : '#2196F3',
                        cursor: p.stock === 0 ? 'not-allowed' : 'pointer'
                      }}
                      onClick={() => handleAddToCart(p)}
                      disabled={p.stock === 0}
                    >
                      {p.stock === 0 ? 'Out of Stock' : added[p.id] ? '✓ Added!' : '+ Cart'}
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

const styles = {
  container: { minHeight: '100vh', background: '#f5f6fa' },
  navbar: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: '#fff', padding: '15px 30px', boxShadow: '0 2px 5px rgba(0,0,0,0.08)' },
  logo: { margin: 0 },
  navLinks: { display: 'flex', alignItems: 'center', gap: '20px' },
  navLink: { color: '#2196F3', textDecoration: 'none', fontWeight: 'bold' },
  adminLink: { color: '#FF9800', textDecoration: 'none', fontWeight: 'bold' },
  logoutBtn: { padding: '8px 16px', background: '#f44336', color: '#fff', border: 'none', borderRadius: '5px', cursor: 'pointer' },
  hero: { background: 'linear-gradient(135deg, #1a1a2e, #16213e)', padding: '40px 30px', textAlign: 'center' },
  heroTitle: { color: '#fff', fontSize: '24px', margin: '0 0 20px' },
  heroSearch: { display: 'flex', alignItems: 'center', background: '#fff', borderRadius: '50px', padding: '5px 20px', maxWidth: '600px', margin: '0 auto', boxShadow: '0 4px 15px rgba(0,0,0,0.2)' },
  searchIcon: { fontSize: '18px', marginRight: '10px' },
  searchInput: { flex: 1, border: 'none', outline: 'none', fontSize: '16px', padding: '10px 0' },
  clearSearch: { cursor: 'pointer', color: '#999', fontSize: '16px' },
  layout: { display: 'flex', gap: '0px', padding: '20px 30px' },
  sidebarWrapper: { marginRight: '20px' },
  sidebar: { background: '#fff', borderRadius: '12px', padding: '20px', boxShadow: '0 2px 8px rgba(0,0,0,0.08)', width: '190px' },
  sidebarHeader: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '20px' },
  sidebarHeaderText: { fontWeight: 'bold', fontSize: '16px' },
  filterBadge: { background: '#2196F3', color: '#fff', borderRadius: '50%', width: '20px', height: '20px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '12px' },
  filterSection: { marginBottom: '20px' },
  filterLabel: { fontSize: '11px', color: '#999', letterSpacing: '1px', margin: '0 0 8px', textTransform: 'uppercase' },
  filterChip: { padding: '8px 12px', borderRadius: '8px', cursor: 'pointer', marginBottom: '5px', fontSize: '14px', color: '#555', background: '#f5f6fa', transition: 'all 0.2s' },
  filterChipActive: { background: '#2196F3', color: '#fff', fontWeight: 'bold' },
  resetBtn: { width: '100%', padding: '9px', background: '#fff', color: '#f44336', border: '1.5px solid #f44336', borderRadius: '8px', cursor: 'pointer', fontSize: '13px', fontWeight: 'bold' },
  main: { flex: 1 },
  topBar: { display: 'flex', alignItems: 'center', gap: '15px', marginBottom: '20px', flexWrap: 'wrap' },
  filterToggle: { display: 'flex', alignItems: 'center', gap: '8px', padding: '9px 18px', background: '#fff', border: '1.5px solid #2196F3', color: '#2196F3', borderRadius: '50px', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px', boxShadow: '0 2px 5px rgba(33,150,243,0.15)' },
  toggleBadge: { background: '#2196F3', color: '#fff', borderRadius: '50%', width: '18px', height: '18px', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '11px' },
  resultCount: { flex: 1, color: '#666', fontSize: '14px', margin: 0 },
  filterTag: { background: '#e3f2fd', color: '#2196F3', padding: '2px 8px', borderRadius: '20px', fontSize: '12px', marginLeft: '8px', cursor: 'pointer' },
  select: { padding: '9px 15px', borderRadius: '8px', border: '1px solid #ddd', fontSize: '14px', background: '#fff', cursor: 'pointer' },
  error: { color: 'red' },
  noResults: { textAlign: 'center', padding: '60px', color: '#666' },
  clearBtn: { marginTop: '10px', padding: '10px 25px', background: '#2196F3', color: '#fff', border: 'none', borderRadius: '8px', cursor: 'pointer' },
  grid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: '20px' },
  card: { background: '#fff', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.08)', overflow: 'hidden', transition: 'transform 0.2s', cursor: 'pointer' },
  productImg: { width: '100%', height: '200px', objectFit: 'cover' },
  noImg: { width: '100%', height: '200px', background: '#f5f6fa', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#ccc', fontSize: '14px' },
  cardBody: { padding: '15px' },
  cardTop: { display: 'flex', gap: '5px', flexWrap: 'wrap', marginBottom: '8px' },
  categoryBadge: { background: '#e3f2fd', color: '#2196F3', padding: '2px 8px', borderRadius: '4px', fontSize: '11px' },
  outOfStockBadge: { background: '#ffebee', color: '#f44336', padding: '2px 8px', borderRadius: '4px', fontSize: '11px' },
  lowStockBadge: { background: '#fff3e0', color: '#FF9800', padding: '2px 8px', borderRadius: '4px', fontSize: '11px' },
  productName: { margin: '0 0 5px', fontSize: '16px', fontWeight: 'bold' },
  desc: { color: '#888', fontSize: '13px', margin: '0 0 10px' },
  cardFooter: { display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
  price: { fontWeight: 'bold', fontSize: '18px', color: '#2196F3', margin: 0 },
  cartBtn: { padding: '8px 16px', color: '#fff', border: 'none', borderRadius: '8px', fontSize: '13px', fontWeight: 'bold' },
};

export default Products;
